INSERT INTO offers (id, title, tagline, description, code, discount_type, discount_value, image_url, is_active, start_date, end_date, associated_product_ids, associated_category_ids, sort_order, created_at, updated_at) VALUES ('offer-1', 'Maison Spring Atelier Special', 'Complimentary 18K Polish Cloth & Silk Travel Case with every order', 'Take 15% off any curated Solid Gold and Pearl combination when you order this week.', 'ATELIER15', 'PERCENTAGE', 15, 'https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?auto=format&fit=crop&q=80&w=1200', true, '2026-08-01T00:00:00Z', '2026-09-30T23:59:59Z', ARRAY['prod-1','prod-2','prod-4'], ARRAY['cat-rings','cat-necklaces','cat-pearls'], 1, '2026-08-18T15:14:45.434Z', '2026-08-18T15:14:45.434Z') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, updated_at = EXCLUDED.updated_at;
INSERT INTO site_settings (id, store_name, tagline, logo_url, instagram_handle, custom_order_message_template, currency_symbol, contact_email, contact_phone, announcement_text, announcement_enabled, announcement_link, hero_headline, hero_subhead, hero_image_url, hero_cta_text, hero_cta_link, default_seo_title, default_seo_description, default_seo_keywords, about_text, atelier_address, hero_eyebrow_text, hero_current_drop_label, hero_current_drop_text, hero_secondary_cta_text, hero_inquiry_card_title, hero_inquiry_card_subtitle, hero_inquiry_card_text, categories_heading, categories_show_all_text, categories_all_pill_label, offers_eyebrow_text, offers_code_label, footer_philosophy_eyebrow, footer_collections_heading, footer_ordering_heading, footer_ordering_text, footer_bottom_tagline) VALUES ('default', 'AURA Fine Jewelry', 'Handcrafted Solid Gold, Pearls & Precious Stones', '', 'aurafinejewelry', 'Hi AURA Atelier, I''m interested in ordering the {product_name} (SKU: {product_sku}, Price: NPR {product_price}). URL: {product_url}', 'NPR ', 'concierge@aurajewelry.com', '+1 (555) 234-8900', 'Complimentary insured worldwide shipping on all atelier drops | DM on Instagram for bespoke sizing', true, '/offers', 'Sculptural Elegance for the Modern Collector', 'Ethically crafted in 18K recycled solid gold and handpicked baroque pearls. Browse our curated catalogue and claim your piece directly via Instagram.', 'https://images.unsplash.com/photo-1515562141207-7a88fb7ce338?auto=format&fit=crop&q=85&w=1600', 'Explore New Drop', '#catalog', 'AURA Fine Jewelry | Pinterest-Inspired Atelier', 'Browse the handcrafted luxury jewelry catalogue from AURA. Order seamlessly via Instagram messaging.', 'fine jewelry, 18k gold, natural pearls, engagement rings, handcrafted jewelry', 'AURA Atelier was founded on the philosophy that fine jewelry should be intimate, tactile, and sculpturally distinct. Each item is produced in limited micro-batches in our studio.', 'SoHo Design District, New York & Paris', 'Editorial 2026', 'Current Atelier Drop', 'Celestial 18K Solid Gold & Baroque Series', 'New Arrivals', 'Instagram Inquiry', 'Atelier Concierge', 'Select any piece from our catalogue to message us directly for bespoke ring sizing and insured global dispatch.', 'Curated Categories', 'Show All Curations', 'All Atelier', 'Limited Seasonal Atelier Event', 'Mention code:', 'Atelier Philosophy', 'Collections', 'Instagram Ordering', 'We provide tailored bespoke sizing, custom diamond settings, and insured global delivery. Inquire directly via Instagram messaging.', 'Curated in Florence & New York') ON CONFLICT (id) DO UPDATE SET store_name = EXCLUDED.store_name, tagline = EXCLUDED.tagline, updated_at = NOW();
